import { render } from '@solidjs/web';
import { For, createStore } from 'solid-js';

function App() {
  let input;
  let nextId = 0;
  const [todos, setTodos] = createStore([]);
  const addTodo = (text) =>
    setTodos((draft) => {
      draft.push({ id: ++nextId, text, completed: false });
    });
  const toggleTodo = (id) =>
    setTodos((draft) => {
      const todo = draft.find((todo) => todo.id === id);
      if (todo) todo.completed = !todo.completed;
    });
  const completeAll = () =>
    setTodos((draft) => {
      for (const todo of draft) todo.completed = true;
    });
  const clearCompleted = () =>
    setTodos((draft) => {
      for (let index = draft.length - 1; index >= 0; index--) {
        if (draft[index].completed) draft.splice(index, 1);
      }
    });
  return (
    <>
      <input ref={input} placeholder="What needs doing?" />
      <button
        onClick={() => {
          if (!input.value.trim()) return;
          addTodo(input.value);
          input.value = '';
        }}
      >
        Add Todo
      </button>
      <button onClick={completeAll}>Complete all</button>
      <button onClick={clearCompleted}>Clear completed</button>
      <For each={todos}>
        {(todo) => (
          <div>
            <input
              type="checkbox"
              checked={todo.completed}
              onChange={() => toggleTodo(todo.id)}
            />
            <span
              style={{
                'text-decoration': todo.completed ? 'line-through' : 'none',
              }}
            >
              {todo.text}
            </span>
          </div>
        )}
      </For>
    </>
  );
}

render(() => <App />, document.getElementById('app'));
